<?phpclass M_users_groups_menus extends CI_Model {    public $_table_name = 'users_groups_menus';    public function __construst() {        parent::__construst();    }    private function generate_where($args) {        if (isset($args['id'])) {            $this->db->where($this->_table_name . ".id", $args['id']);        }        if (isset($args['in_id'])) {            $this->db->where_in($this->_table_name . ".id", $args['in_id']);        }        if (isset($args['group_id'])) {            $this->db->where($this->_table_name . ".group_id", $args['group_id']);        }        if (isset($args['menu_id'])) {            $this->db->where($this->_table_name . ".menu_id", $args['menu_id']);        }        if (isset($args['status'])) {            $this->db->where($this->_table_name . ".status", $args['status']);        }    }    private function generate_order_by($args) {        $allow_sort = array("DESC", "ASC", "RANDOM");        if (isset($args['order_by']) && is_array($args['order_by']) && !empty($args['order_by'])) {            foreach ($args['order_by'] as $key => $value) {                $sort = in_array($value, $allow_sort) ? $value : "DESC";                $this->db->order_by($this->_table_name . '.' . $key, $sort);            }        }    }    public function gets($args, $perpage = 5, $offset = -1) {        $this->db->select();        $this->db->from($this->_table_name);        $this->generate_where($args);        $this->generate_order_by($args);        if ($offset >= 0) {            $this->db->limit($perpage, $offset);        }        $query = $this->db->get();        return $query->result_array();    }    public function counts($args) {        $this->db->select();        $this->db->from($this->_table_name);        $this->generate_where($args);        $query = $this->db->get();        return $query->num_rows();    }    public function get($id) {        $this->db->select();        $this->db->from($this->_table_name);        $this->db->where($this->_table_name . '.id', $id);        $query = $this->db->get();        return $query->row_array();    }    public function get_by($args) {        $this->db->select();        $this->db->from($this->_table_name);        $this->generate_where($args);        $this->generate_order_by($args);        $query = $this->db->get();        return $query->row_array();    }    public function add($data = array()) {        if (empty($data)) {            return 0;        }        $query = $this->db->insert($this->_table_name, $data);        $insert_id = $this->db->insert_id();        return isset($query) ? $insert_id : 0;    }    public function update($id, $data) {        if (empty($data)) {            return false;        }        $this->db->where('id', $id);        $query = $this->db->update($this->_table_name, $data);        return isset($query) ? true : false;    }    public function delete($id) {        $this->db->where('id', $id);        $query = $this->db->delete($this->_table_name);        return isset($query) ? true : false;    }}/* End of file M_users_groups_menus.php *//* Location: ./application/modules/users/models/M_users_groups_menus.php */